INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (7, 'Kancing tidak terpasang dengan kuat', 'Kancing longgar, jahitan tidak mencengkeram kancing dengan baik, atau kancing mudah terlepas.', 'Jumlah stitch tidak sesuai, posisi kancing kurang tepat, ukuran atau ketebalan kancing tidak sesuai, atau pengaturan feed bermasalah.', 'Periksa posisi kancing dan sesuaikan jumlah stitch dengan kebutuhan. Pastikan ukuran kancing berada dalam rentang spesifikasi mesin dan gunakan attachment yang sesuai bila diperlukan.', 'Matikan mesin sebelum melakukan penyetelan area penjepit kancing atau attachment.', 'Data spesifikasi JUKI MB-1373 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (7, 'Benang sering putus saat memasang kancing', 'Benang putus selama proses jahit kancing atau sebelum siklus selesai.', 'Jarum TQ×1 tidak sesuai atau rusak, jalur benang kurang tepat, tegangan benang terlalu tinggi, atau material dan kancing tidak sesuai.', 'Periksa jalur benang dan tegangan. Gunakan jarum TQ×1 yang sesuai dan ganti jika bengkok atau tumpul.', 'Matikan mesin sebelum mengganti jarum atau melakukan penyesuaian pada jalur benang.', 'Data spesifikasi jarum JUKI MB-1373 dan panduan troubleshooting umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (7, 'Posisi kancing bergeser', 'Kancing terpasang tidak tepat pada posisi yang diinginkan atau jarak antar lubang tidak sesuai.', 'Pengaturan feed crosswise atau lengthwise tidak tepat, penjepit kancing kurang stabil, atau posisi material tidak benar.', 'Periksa posisi attachment dan sesuaikan feed crosswise serta lengthwise. Pastikan material terpasang stabil sebelum siklus dimulai.', 'Matikan mesin sebelum melakukan penyetelan attachment atau mekanisme feed.', 'Data spesifikasi feed JUKI MB-1373');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (7, 'Bentuk jahitan U atau X tidak sesuai', 'Pola jahitan pada kancing tidak membentuk U atau X dengan benar.', 'Pemilihan pola atau penyetelan feed tidak tepat, atau mekanisme gerak jarum dan feed mengalami gangguan.', 'Periksa pengaturan stitching shape dan sesuaikan feed length. Pastikan pola yang dipilih sesuai dengan jenis kancing dan kebutuhan jahitan.', 'Matikan mesin sebelum memeriksa atau menyetel mekanisme jahit.', 'Data spesifikasi stitching shape JUKI MB-1373');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (7, 'Jumlah stitch tidak sesuai', 'Jumlah tusukan jahitan lebih sedikit atau lebih banyak dari pengaturan yang dipilih.', 'Pengaturan jumlah stitch tidak tepat atau mekanisme kontrol siklus mengalami gangguan.', 'Periksa pilihan jumlah stitch yang tersedia dan pastikan pengaturan sesuai kebutuhan. MB-1373 mendukung 8, 16, atau 32 stitches.', 'Matikan mesin sebelum memeriksa mekanisme kontrol atau melakukan penyetelan.', 'Data spesifikasi number of stitches JUKI MB-1373');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (7, 'Jarum tidak bekerja normal', 'Jarum bengkok, patah, atau gerakan jarum tidak sesuai selama proses pemasangan kancing.', 'Jarum TQ×1 rusak atau tidak terpasang benar, kancing terlalu tebal, atau terdapat hambatan pada mekanisme needle bar.', 'Periksa pemasangan jarum dan kondisi needle bar. Gunakan ukuran jarum yang sesuai dengan material dan kancing.', 'Matikan mesin dan lepaskan sumber listrik sebelum mengganti jarum atau memeriksa needle bar.', 'Data spesifikasi needle dan needle bar stroke JUKI MB-1373');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (7, 'Pelumasan tidak normal', 'Mesin terasa kasar, suara mekanis meningkat, atau bagian bergerak tidak bekerja dengan lancar.', 'Oli tidak mencukupi atau proses oiling tidak dilakukan dengan benar.', 'Periksa titik pelumasan dan gunakan JUKI New Defrix Oil No. 1 atau ISO VG7 sesuai spesifikasi. Lakukan pelumasan sesuai prosedur perawatan.', 'Matikan mesin sebelum melakukan pelumasan dan hindari kontak dengan bagian bergerak.', 'Data spesifikasi lubrication JUKI MB-1373');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (7, 'Benang atau jahitan akhir mudah terurai', 'Ujung jahitan atau benang akhir mudah terlepas setelah siklus pemasangan kancing selesai.', 'Thread-fray-prevention tidak sesuai pengaturan atau kondisi benang tidak sesuai dengan material.', 'Periksa pengaturan thread-fray-prevention dan pastikan fitur berada pada kondisi yang sesuai. Periksa juga kondisi dan tegangan benang.', 'Matikan mesin sebelum melakukan penyetelan mekanisme atau sistem pengendalian benang.', 'Data fitur thread-fray-prevention JUKI MB-1373');
